import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { mkdir, readFile, writeFile } from 'node:fs/promises';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const repoRoot = path.resolve(__dirname, '..');

const files = [
  path.join(repoRoot, 'lib/interaction/direct-manipulation.js'),
  path.join(repoRoot, 'lib/runtime/timeline.js'),
  path.join(repoRoot, 'lib/testing/harness.js'),
];

const outputPath = path.join(repoRoot, 'templates/shared-inline-snippet.js');

function stripModuleSyntax(source) {
  return source
    .replace(/^import[\s\S]*?;\n?/gm, '')
    .replace(/^export\s*\{[^}]*\}\s*from\s*['"][^'"]+['"];?\n?/gm, '')
    .replace(/^export \{[\s\S]*?\};?$/gm, '')
    .replace(/^export /gm, '')
    .trim();
}

async function buildInlineSnippet() {
  const sections = await Promise.all(files.map((filePath) => readFile(filePath, 'utf8')));
  const body = sections.map(stripModuleSyntax).join('\n\n');
  const snippet = `// Generated by scripts/build-shared-inline-bundle.mjs
// Paste this inside a <script type="module"> block after importing THREE.

${body}

const ChemSharedLib = {
  THREE,
  updatePointerFromEvent,
  setPointerCaptureSafe,
  releasePointerCaptureSafe,
  setControlsDragging,
  intersectPointerPlane,
  clamp01,
  lerp,
  smoothstep01,
  segment,
  sequenceProgress,
  getCanvasBox,
  canvasPoint,
  projectWorldToCanvas,
  installFlameTestHarness,
};

globalThis.ChemSharedLib = ChemSharedLib;
`;

  await mkdir(path.dirname(outputPath), { recursive: true });
  await writeFile(outputPath, `${snippet}\n`, 'utf8');
  return outputPath;
}

const builtPath = await buildInlineSnippet();
console.log(`Built shared inline snippet: ${builtPath}`);
